     '2026 BIR Interactive Tax Calendar', 'Bureau of Internal Revenue',
     'https://bir-cdn.bir.gov.ph/BIR/pdf/RMC%20No.%20110-2025.pdf',
     date '2025-12-23', date '2026-01-01', date '2026-10-11',
     'verified', 'active',
     'Official circular announcing the 2026 BIR Interactive Tax Calendar.',
     jsonb_build_object('calendarYear', 2026, 'sourceKind', 'official_circular')),
    ('BIR-2026-INTERACTIVE-TAX-CALENDAR', 'bir_calendar',
     'BIR Interactive Tax Calendar 2026 — published dataset reference',
     'Bureau of Internal Revenue',
     'https://www.bir.gov.ph/Tax-Reminder?q=Orus',
     null, date '2026-01-01', date '2026-10-11',
     'verified', 'active',
     'Official BIR public calendar dataset 1135. Rows are loaded exactly as published after structural normalization; no future dates are inferred.',
     jsonb_build_object(
       'datasetTemplateId', 1135,
       'datasetEndpoint', 'https://bir-cms-ws.bir.gov.ph/api/pub/templates/1135/datasets?per_page=3000',
       'coverageStart', '2026-01-01',
       'coverageThrough', '2026-10-31',
       'missingOfficialPublicationMonths', jsonb_build_array('2026-11', '2026-12')
     ))
  on conflict (code) do update set
    title = excluded.title, source_url = excluded.source_url,
    publication_date = excluded.publication_date, effectivity_date = excluded.effectivity_date,
    retrieval_date = excluded.retrieval_date, verification_status = excluded.verification_status,
    status = excluded.status, notes = excluded.notes, metadata = excluded.metadata;

  select id into calendar_source_id
  from public.regulatory_issuances
  where code = 'BIR-2026-INTERACTIVE-TAX-CALENDAR';

  insert into public.regulatory_issuance_citations
    (issuance_id, locator, page_reference, section_reference, quote_or_summary)
  select id, 'official-calendar-page', 'Interactive Tax Calendar', 'Calendar Schedule',
    'Published 2026 dated calendar rows from BIR public dataset template 1135.'
  from public.regulatory_issuances s
  where s.code = 'BIR-2026-INTERACTIVE-TAX-CALENDAR'
    and not exists (
      select 1 from public.regulatory_issuance_citations c
      where c.issuance_id = s.id
        and c.locator = 'official-calendar-page'
        and c.section_reference = 'Calendar Schedule'
    );

  select id into calendar_citation_id
  from public.regulatory_issuance_citations
  where issuance_id = calendar_source_id
    and locator = 'official-calendar-page'
    and section_reference = 'Calendar Schedule';

  insert into public.regulatory_issuance_citations
    (issuance_id, locator, page_reference, section_reference, quote_or_summary)
  select id, 'rmc-110-2025', 'Circular', '2026 BIR Interactive Tax Calendar',
    'Revenue Memorandum Circular No. 110-2025 announces the 2026 BIR Interactive Tax Calendar.'
  from public.regulatory_issuances s
  where s.code = 'BIR-RMC-110-2025'
    and not exists (
      select 1 from public.regulatory_issuance_citations c
      where c.issuance_id = s.id
        and c.locator = 'rmc-110-2025'
        and c.section_reference = '2026 BIR Interactive Tax Calendar'
    );

  insert into public.rules (code, rule_kind, title, status)
  values ('BIR-2026-PUBLISHED-CALENDAR-REFERENCE', 'deadline',
    'Published BIR calendar date reference — 2026', 'active')
  on conflict (code) do update set title = excluded.title, status = excluded.status;

  select id into deadline_rule_id
  from public.rules where code = 'BIR-2026-PUBLISHED-CALENDAR-REFERENCE';

  insert into public.rule_versions
    (rule_id, version_label, effective_from, status, verification_status,
     strategy_code, parameters)
  values
    (deadline_rule_id, '2026.1', date '2026-01-01', 'approved', 'partially_verified',
     'published_calendar_reference',
     jsonb_build_object(
       'sourceCode', 'BIR-2026-INTERACTIVE-TAX-CALENDAR',
       'datasetTemplateId', 1135,
       'coverageThrough', '2026-10-31',
       'baseStatutoryDeadline', 'unresolved',
       'adjustedStatutoryDeadline', 'published official date'
     ))
  on conflict (rule_id, version_label) do update set
    status = excluded.status, verification_status = excluded.verification_status,
    strategy_code = excluded.strategy_code, parameters = excluded.parameters;

  select id into deadline_rule_version_id
  from public.rule_versions
  where rule_id = deadline_rule_id and version_label = '2026.1';

  insert into public.rule_version_sources (rule_version_id, issuance_id, citation_id)
  values (deadline_rule_version_id, calendar_source_id, calendar_citation_id)
  on conflict (rule_version_id, issuance_id, citation_id) do nothing;

  insert into public.deadline_policies
    (code, title, strategy_code, adjustment_code, parameters, effective_from,
     status, verification_status)
  values
    ('BIR-2026-PUBLISHED-CALENDAR-DATE', 'Published BIR calendar date — reference only',
     'fixed_date', 'none',
     jsonb_build_object(
       'sourceCode', 'BIR-2026-INTERACTIVE-TAX-CALENDAR',
       'baseDate', 'unresolved',
       'publishedDate', 'official calendar date',
       'packageTarget', 'not generated'
     ),
     date '2026-01-01', 'approved', 'partially_verified')
  on conflict (code) do update set
    title = excluded.title, parameters = excluded.parameters,
    status = excluded.status, verification_status = excluded.verification_status;

  select id into v_deadline_policy_id
  from public.deadline_policies where code = 'BIR-2026-PUBLISHED-CALENDAR-DATE';

  insert into public.deadline_policy_sources (deadline_policy_id, issuance_id, citation_id)
  values (v_deadline_policy_id, calendar_source_id, calendar_citation_id)
  on conflict (deadline_policy_id, issuance_id, citation_id) do nothing;

  for form_record in
    select * from jsonb_to_recordset(payload->'forms') as f(number text, title text)
  loop
    insert into public.bir_forms
      (form_number, title, revision_label, status, verification_status, notes)
    values
      (form_record.number, form_record.title, '2026 calendar reference',
       'active', 'partially_verified',
       'Referenced by the official 2026 BIR Interactive Tax Calendar. Form revision and current applicability require the corresponding BIR form/instruction source.')
    on conflict (form_number, revision_label) do update set
      title = excluded.title, status = excluded.status,
      verification_status = excluded.verification_status, notes = excluded.notes;
  end loop;

  for requirement_record in
    select * from jsonb_to_recordset(payload->'requirements')
      as r(code text, name text, type text, category text, frequency text, forms jsonb)
  loop
    insert into public.bir_requirements
      (requirement_code, requirement_name, requirement_type, operating_category,
       frequency_label, legal_cadence_code, applicability_class, status,
       verification_status, effective_from, notes)
    values
      (requirement_record.code, requirement_record.name, requirement_record.type,
       requirement_record.category, requirement_record.frequency, requirement_record.frequency,
       'unresolved', 'active', 'partially_verified', date '2026-01-01',
       'Calendar-backed requirement identity. Applicability is not inferred from a calendar row and requires the governed client profile/rule sources.')
    on conflict (requirement_code) do update set
      requirement_name = excluded.requirement_name,
      requirement_type = excluded.requirement_type,
      operating_category = excluded.operating_category,
      frequency_label = excluded.frequency_label,
      legal_cadence_code = excluded.legal_cadence_code,
      status = case when public.bir_requirements.status in ('retired', 'superseded')
        then public.bir_requirements.status else 'active' end,
      verification_status = 'partially_verified',
      effective_from = coalesce(public.bir_requirements.effective_from, excluded.effective_from),
      notes = excluded.notes;
  end loop;

  for requirement_record in
    select * from jsonb_to_recordset(payload->'requirements')
      as r(code text, name text, type text, category text, frequency text, forms jsonb)
  loop
    insert into public.bir_requirement_versions
      (requirement_id, version_label, effective_from, status, verification_status,
       applicability_strategy, period_strategy, deadline_policy_id, metadata)
    select requirement.id, '2026-calendar-reference', date '2026-01-01',
      'approved', 'partially_verified', 'profile_and_rule_review_required',
      requirement.frequency_label, v_deadline_policy_id,
      jsonb_build_object('sourceCode', 'BIR-2026-INTERACTIVE-TAX-CALENDAR', 'datasetTemplateId', 1135)
    from public.bir_requirements requirement
    where requirement.requirement_code = requirement_record.code
    on conflict (requirement_id, version_label) do update set
      status = excluded.status, verification_status = excluded.verification_status,
      applicability_strategy = excluded.applicability_strategy,
      period_strategy = excluded.period_strategy,
      deadline_policy_id = excluded.deadline_policy_id,
      metadata = excluded.metadata;
  end loop;

  for item in
    select * from jsonb_to_recordset(payload->'rows')
      as i(id text, calendar_date date, label text, code text, forms jsonb, category text, frequency text, type text)
  loop
    select v.id into version_record
    from public.bir_requirement_versions v
    join public.bir_requirements r on r.id = v.requirement_id
    where r.requirement_code = item.code
      and v.version_label = '2026-calendar-reference';

    insert into public.requirement_version_sources (requirement_version_id, issuance_id, citation_id)
    values (version_record.id, calendar_source_id, calendar_citation_id)
    on conflict (requirement_version_id, issuance_id, citation_id) do nothing;

    for form_record in
      select value::text as number from jsonb_array_elements_text(item.forms)
    loop
      insert into public.requirement_version_forms (requirement_version_id, form_id, relationship_type)
      select version_record.id, id, 'primary_form'
      from public.bir_forms
      where form_number = form_record.number
        and revision_label = '2026 calendar reference'
      on conflict (requirement_version_id, form_id) do nothing;
    end loop;

    insert into public.monthly_calendar_versions
      (calendar_month, version_number, status, prepared_by, prepared_at,
       approved_by, approved_at, released_at, partial_release, source_set,
       reconciliation_summary, release_note)
    values
      (date_trunc('month', item.calendar_date)::date, 1, 'released',
       coalesce((select id from public.app_users where display_name = 'Liezl Maigue' and is_active limit 1),
                (select id from public.app_users where is_active limit 1)), now(),
       coalesce((select id from public.app_users where display_name = 'Liezl Maigue' and is_active limit 1),
                (select id from public.app_users where is_active limit 1)), now(), now(), true,
       jsonb_build_array('BIR-RMC-110-2025', 'BIR-2026-INTERACTIVE-TAX-CALENDAR'),
       jsonb_build_object('officialDatasetRows', 139, 'coverageThrough', '2026-10-31',
         'unresolvedFutureMonths', jsonb_build_array('2026-11', '2026-12'),
         'applicability', 'not derived from calendar'),
       'Official BIR 2026 published dates loaded as a partial reference release. November and December remain unreleased until BIR publishes them.')
    on conflict (calendar_month, version_number) do update set
      status = 'released', prepared_by = excluded.prepared_by, prepared_at = excluded.prepared_at,
      approved_by = excluded.approved_by, approved_at = excluded.approved_at,
      released_at = excluded.released_at, partial_release = true,
      source_set = excluded.source_set, reconciliation_summary = excluded.reconciliation_summary,
      release_note = excluded.release_note;

    select * into month_record
    from public.monthly_calendar_versions
    where calendar_month = date_trunc('month', item.calendar_date)::date
      and version_number = 1;

    insert into public.monthly_calendar_entries
      (calendar_version_id, requirement_id, requirement_version_id, external_requirement_label,
       period_or_event, base_statutory_deadline, adjusted_statutory_deadline,
       tmf_package_target, comparison_status, unresolved_reason, source_issuance_id,
       source_locator, affected_population, notes, publication_status,
       published_operational_deadline, deadline_explanation)
    select month_record.id, r.id, version_record.id, item.label, item.label, null, item.calendar_date,
      null, 'not_comparable',
      'Official calendar date is present; the underlying base statutory rule and approved adjustment basis are not encoded by this calendar source alone.',
      calendar_source_id, 'dataset:1135/record:' || item.id,
      jsonb_build_object('sourceRecordId', item.id, 'officialDate', item.calendar_date),
      'Reference release only. Do not generate client work from this row until applicability and rule reconciliation is approved.',
      'published', item.calendar_date,
      jsonb_build_object('sourceCode', 'BIR-2026-INTERACTIVE-TAX-CALENDAR',
        'officialPublishedDate', item.calendar_date, 'baseStatutoryDeadline', 'unresolved',
        'adjustedStatutoryDeadline', item.calendar_date, 'tmfPackageTarget', 'not generated')
    from public.bir_requirements r
    where r.requirement_code = item.code
      and not exists (
        select 1 from public.monthly_calendar_entries existing
        where existing.calendar_version_id = month_record.id
          and existing.source_locator = 'dataset:1135/record:' || item.id
      );

    insert into public.published_calendar_entries
      (calendar_year, requirement_id, requirement_version_id, external_requirement_label,
       period_or_event, adjusted_statutory_deadline, official_published_date,
       validation_status, source_issuance_id, source_locator, notes)
    select 2026, r.id, version_record.id, item.label, item.label, item.calendar_date, item.calendar_date,
      'unresolved', calendar_source_id, 'dataset:1135/record:' || item.id,
      'Official 2026 published date; base deadline and applicability remain separately governed.'
    from public.bir_requirements r
    where r.requirement_code = item.code
      and not exists (
        select 1 from public.published_calendar_entries existing
        where existing.calendar_year = 2026
          and existing.source_locator = 'dataset:1135/record:' || item.id
      );
  end loop;
end
$migration$;
